// 1. Ambil payload dari Webhook
const raw = $input.first().json;
const payload = raw.body || raw; 

const assetCode = payload.asset_code || '-';

// 2. Logika Cooldown 10 Menit (Anti-Spam)
// (Kita tetap pakai cooldown agar jika perangkat flapping, tidak spam pesan)
const staticData = $getWorkflowStaticData('global');
const COOLDOWN_MS = 10 * 60 * 1000; 
const now = Date.now();
const lastSent = staticData[`last_sent_rec_${assetCode}`] || 0; // Key dibedakan untuk recovery
const timeSinceLastSent = now - lastSent;

if (timeSinceLastSent < COOLDOWN_MS) {
  return []; // Mencegah spam
}

staticData[`last_sent_rec_${assetCode}`] = now;

// 3. Ubah format waktu (recovered_at)
let recoveredFormatted = payload.recovered_at || payload.timestamp || '-';
if (recoveredFormatted !== '-') {
  try {
    recoveredFormatted = new Date(recoveredFormatted).toLocaleString('id-ID', {
      timeZone: 'Asia/Jakarta',
      dateStyle: 'medium',
      timeStyle: 'short'
    }) + ' WIB';
  } catch (e) {}
}

// 4. Siapkan Teks Fallback & Prompt AI
const messageFallback = `🟢 RECOVERY ALERT — ${payload.asset_name || '-'}\n\n📊 Status: ONLINE\n⏰ Waktu Pulih: ${recoveredFormatted}\n\nℹ️ Notifikasi Standar (AI Gemini sedang limit/down)`;

const promptAI = `Kamu adalah AI Network Analyst profesional untuk sistem T-AIMS.
Perangkat berikut baru saja PULIH (ONLINE kembali):
- Nama: ${payload.asset_name || '-'}
- Kode: ${assetCode}
- Kategori: ${payload.category || '-'}
- Waktu Pulih: ${recoveredFormatted}

Tugasmu:
1. Berikan ucapan singkat bahwa perangkat sudah normal kembali.
2. Berikan 1 saran pencegahan agar perangkat tidak mati lagi (sesuaikan dengan kategori perangkat).

Format output (WAJIB teks biasa, jangan JSON):
🟢 RECOVERY ALERT — ${payload.asset_name || '-'}

📊 Status: ONLINE
⏰ Waktu Pulih: ${recoveredFormatted}

🤖 Analisis AI:
[Ucapan dan saran pencegahan dari kamu]`;

// 5. Return data
return {
  json: {
    asset_code: assetCode,
    asset_name: payload.asset_name || '-',
    category: payload.category || '-',
    recovered_at: recoveredFormatted, 
    message: messageFallback, 
    prompt_ai: promptAI       
  }
};
